1	import {
2	  MapLayerMouseEvent,
3	  MapLayerTouchEvent,
4	  MapGeoJSONFeature,
5	  Map as MaplibreMap,
6	} from 'maplibre-gl';
7	import {BLOCK_HOVER_LAYER_ID} from '@/app/constants/map/layerIds';
8	import {boxAroundPoint} from '@utils/map/bboxAroundPoint';
9	import {filterFeatures} from '@utils/map/filterFeatures';
10	import {fastUniqBy} from '@utils/arrays';
11	import {demographyService} from '../demography/demographyService';
12	
13	/**
14	 * Module-scoped memo of the last computed result, keyed by the sorted set of
15	 * county FIPS codes under the brush. Consecutive mousemove events over the
16	 * same set of counties (the common case while dragging) skip the
17	 * demography lookup + filterFeatures pass entirely.
18	 */
19	let lastCountyKey: string | null = null;
20	let lastResult: MapGeoJSONFeature[] | undefined;
21	
22	/**
23	 * getFeaturesIntersectingCounties
24	 * Get the features intersecting the counties under the brush footprint,
25	 * so a brush that straddles a county line paints both counties' blocks
26	 * instead of only the county under the cursor point.
27	 * @param map - MaplibreMap | null, the maplibre map instance
28	 * @param e - MapLayerMouseEvent | MapLayerTouchEvent, the event object
29	 * @param brushSize - number, the size of the brush
30	 * @returns MapGeoJSONFeature[] | undefined - An array of map features or undefined
31	 */
