243	    if (hash === this.overlayHash) return;
244	    this.overlayTable = table(data)
245	      .derive(getColumnDerives(columns))
246	      .dedupe('path')
247	      .derive(getPctDerives(columns));
248	    this.overlayHash = hash;
249	  }
