258	      zoneAssignments instanceof Map
259	        ? Array.from(zoneAssignments.entries()).map(([path, zone]) => ({path, zone}))
260	        : zoneAssignments;
261	    const normalizedAssignmentRows = assignmentRows.filter(
262	      ({path, zone}) => Boolean(path) && zone !== undefined && zone !== null
263	    );
264	    const rows = normalizedAssignmentRows.length;
265	    const zoneColumns = {
266	      path: new Array(rows),
267	      zone: new Array(rows),
268	    };
269	    normalizedAssignmentRows.forEach(({path, zone}, i) => {
270	      zoneColumns.path[i] = path;
271	      zoneColumns.zone[i] = zone;
272	    });
273	    this.zoneTable = table(zoneColumns);
274	  }
