305	  private applyCoalitionColumns(rows: SummaryTable, coalitionGroups: CoalitionGroupKey[]) {
306	    const coalitionColumnsByUniverse: Record<
307	      CoalitionUniverse,
308	      Array<AllTabularColumns[number]>
309	    > = {
310	      TOTPOP: this.getCoalitionColumns(coalitionGroups, SUMMARY_TYPES.TOTPOP),
311	      VAP: this.getCoalitionColumns(coalitionGroups, SUMMARY_TYPES.VAP),
312	    };
313	    rows.forEach(row => {
314	      const record = asNumericRecord(row);
315	      Object.values(COALITION_UNIVERSES).forEach(universe => {
316	        const coalitionVariable = COALITION_VARIABLE_BY_UNIVERSE[universe];
317	        const totalColumn = COALITION_TOTAL_COLUMN_BY_UNIVERSE[universe];
318	        const coalitionCount = coalitionColumnsByUniverse[universe].reduce((sum, column) => {
319	          const value = record[column];
320	          return sum + (Number.isFinite(value) ? value : 0);
321	        }, 0);
322	        const totalValue = record[totalColumn];
323	        record[coalitionVariable] = coalitionCount;
324	        record[`${coalitionVariable}_pct`] =
325	          Number.isFinite(totalValue) && totalValue > 0 ? coalitionCount / totalValue : NaN;
326	      });
327	    });
328	  }
