330	  private updateCoalitionMaxValues(rows: SummaryTable) {
331	    const maxValues = {...(this.zoneStats.maxValues ?? {})} as Record<string, number>;
332	    Object.values(COALITION_UNIVERSES).forEach(universe => {
333	      const variable = COALITION_VARIABLE_BY_UNIVERSE[universe];
334	      const pctVariable = `${variable}_pct`;
335	      const rawMax = Math.max(0, ...rows.map(row => asNumericRecord(row)[variable] ?? 0));
336	      const pctMax = Math.max(
337	        0,
338	        ...rows
339	          .map(row => asNumericRecord(row)[pctVariable])
340	          .filter(value => Number.isFinite(value))
341	      );
342	      maxValues[variable] = rawMax;
343	      maxValues[pctVariable] = pctMax;
344	    });
345	    this.zoneStats.maxValues = maxValues as MaxValues & Record<string, number>;
346	  }
