382	  /**
383	   * Whether the currently loaded units span more than one county. Early-exits
384	   * on the second distinct county FIPS found — callers only need "more than
385	   * one," never the actual count or the list, so there's no reason to scan
386	   * past that. `path` values look like `vtd:48001000001` (or without a type
387	   * prefix for some geography levels) — the state+county FIPS is always the
388	   * 5 digits right after any `<type>:` prefix.
389	   */
390	  spansMultipleCounties(): boolean {
391	    if (!this.table) return false;
392	    const paths = this.table.array(this.id_col) as string[];
393	    if (!paths.length) return false;
394	    const toGeoid = (path: string) =>
395	      path.includes(':') ? path.slice(path.indexOf(':') + 1) : path;
396	    const firstCountyFips = toGeoid(paths[0]).slice(0, 5);
397	    for (let i = 1; i < paths.length; i++) {
398	      if (!toGeoid(paths[i]).startsWith(firstCountyFips)) return true;
399	    }
400	    return false;
401	  }
