403	  /**
404	   * Calculates the populations based on zone assignments.
405	   *
406	   * @param zoneAssignments - The zone assignments to use for calculation.
407	   * @returns The calculated populations.
408	   */
409	  calculatePopulations(
410	    zoneAssignments?: PopulationAssignments,
411	    coalitionGroups: CoalitionGroupKey[] = []
412	  ): {ok: true; table: SummaryTable} | {ok: false} {
413	    if (this.isPublicSource) {
414	      return this.calculatePopulationsFromZoneTable(coalitionGroups);
415	    }
416	    this.updateZoneTable(zoneAssignments ?? getActivePopulationAssignments());
417	
418	    if (!this.table || !this.zoneTable) {
419	      return {
420	        ok: false,
421	      };
422	    }
423	    const joinedTable = this.table.join_full(this.zoneTable, ['path', 'path']);
424	    const missingPopulations = joinedTable.filter(
425	      escape(
426	        (row: TableRow & {zone: NullableZone}) =>
427	          row['total_pop_20'] === undefined && row['zone'] !== undefined
428	      )
429	    );
430	    if (missingPopulations.size) {
431	      return {
432	        ok: false,
433	      };
434	    }
435	    const columns = this.table.columnNames();
436	    const populationsTable = joinedTable
437	      .groupby('zone')
438	      .rollup(getRollups(columns, 'sum'))
439	      .derive(getPctDerives(columns));
440	
441	    const maxRollups = populationsTable
442	      .rollup(getRollups(columns, 'max'))
443	      .objects()[0] as MaxValues;
444	
445	    return this.finalizePopulations(
446	      populationsTable.objects() as SummaryTable,
447	      maxRollups,
448	      coalitionGroups
449	    );
450	  }
451	
452	  /**
453	   * View-mode counterpart to the block-join path above. `this.table` is already
454	   * one row per zone (the backend pre-aggregates demography per district — see
455	   * document.district_unions), so population calculation is just deriving `zone`
456	   * from `path` and percent columns; no assignments/join concept applies.
457	   */
458	  private calculatePopulationsFromZoneTable(
459	    coalitionGroups: CoalitionGroupKey[]
460	  ): {ok: true; table: SummaryTable} | {ok: false} {
461	    if (!this.table) {
462	      return {ok: false};
463	    }
464	    const columns = this.table.columnNames();
465	    const populationsTable = this.table
466	      .derive({
467	        zone: escape((row: TableRow) => (row.path === '__unassigned__' ? null : +row.path)),
468	      })
469	      .derive(getPctDerives(columns));
470	
471	    const maxRollups = populationsTable
472	      .rollup(getRollups(columns, 'max'))
473	      .objects()[0] as MaxValues;
474	
475	    return this.finalizePopulations(
476	      populationsTable.objects() as SummaryTable,
477	      maxRollups,
478	      coalitionGroups
479	    );
480	  }
481	
482	  /**
483	   * Shared tail of both population-calculation paths: fills in zero rows for
484	   * unpainted/unassigned zones, applies coalition columns, sorts, and updates
485	   * zoneStats/summaryStats derived from the final per-zone table.
486	   */
487	  private finalizePopulations(
488	    zonePopulationsTable: SummaryTable,
489	    maxRollups: MaxValues | undefined,
490	    coalitionGroups: CoalitionGroupKey[]
491	  ): {ok: true; table: SummaryTable} {
492	    const mapState = useMapStore.getState();
493	    const mapMode = useMapControlsStore.getState().mapMode;
494	    const zoneIds =
495	      mapMode === MAP_MODES.COI
496	        ? sortCommunitiesByRenderOrder(mapState.communities).map(community => community.id)
497	        : Array.from(
498	            {length: mapState.mapDocument?.num_districts ?? FALLBACK_NUM_DISTRICTS},
499	            (_, i) => i + 1
500	          );
501	
502	    if (maxRollups) {
503	      this.zoneStats.maxValues = maxRollups as MaxValues & Record<string, number>;
504	    }
505	    const populatedZoneIds = new Set(
506	      zonePopulationsTable
507	        .map(row => row.zone)
508	        .filter((zone): zone is number => zone !== undefined && zone !== null)
509	    );
510	    for (const zoneId of zoneIds) {
511	      if (!populatedZoneIds.has(zoneId)) {
512	        // @ts-ignore
513	        zonePopulationsTable.push({zone: zoneId, total_pop_20: 0});
514	      }
515	    }
516	    this.applyCoalitionColumns(zonePopulationsTable, coalitionGroups);
517	    this.updateCoalitionMaxValues(zonePopulationsTable);
518	    this.populations = zonePopulationsTable.sort((left, right) => {
519	      if (left.zone === undefined || left.zone === null) return 1;
520	      if (right.zone === undefined || right.zone === null) return -1;
521	      if (mapMode === MAP_MODES.COI) {
522	        return compareCoiZonesByRenderOrder(left.zone, right.zone, mapState.communities);
523	      }
524	      return left.zone - right.zone;
525	    });
526	    const popNumbers = this.populations
527	      .filter(row => row.zone !== undefined && row.zone !== null)
528	      .map(row => row.total_pop_20);
529	    this.zoneStats.maxPopulation = Math.max(...popNumbers);
530	    this.zoneStats.minPopulation = Math.min(...popNumbers);
531	    this.zoneStats.range = this.zoneStats.maxPopulation - this.zoneStats.minPopulation;
532	    this.summaryStats.unassigned = this.populations.find(f => !f.zone)?.total_pop_20 ?? 0;
533	    this.zoneStats.paintedZones = popNumbers.filter(pop => pop > 0).length;
534	    return {
535	      ok: true,
536	      table: this.populations,
537	    };
538	  }
