540	  /**
541	   * Calculates the summary statistics.
542	   */
543	  updateSummaryStats(): void {
544	    if (!this.table) return;
545	    const columns = this.table.columnNames();
546	    this.table = this.table.derive(getPctDerives(columns));
547	    const summaries = this.table.rollup(getRollups(columns, 'sum')).objects()[0] as SummaryRecord;
548	    const mapState = useMapStore.getState();
549	    const mapDocument = mapState.mapDocument;
550	    const mapMode = useMapControlsStore.getState().mapMode;
551	    const numZones =
552	      mapMode === MAP_MODES.COI
553	        ? Math.max(mapState.communities.length, FALLBACK_NUM_COMMUNITIES)
554	        : (mapDocument?.num_districts ?? FALLBACK_NUM_DISTRICTS);
555	
556	    Object.entries(summaryStatsConfig).forEach(([key, config]) => {
557	      const summaryStats: Partial<DemographyRow> = {};
558	      config['columns'].forEach(col => (summaryStats[col] = summaries[col]));
559	      // @ts-ignore
560	      this.summaryStats[key] = summaryStats as SummaryRecord;
561	    });
562	
563	    this.summaryStats.totalPopulation = summaries.total_pop_20;
564	    this.summaryStats.idealpop = Math.round(summaries.total_pop_20 / numZones);
565	
566	    const universeRow: Record<string, unknown> = {...summaries, zone: 0};
567	    possibleRollups.forEach(rollup => {
568	      const totalVal = summaries[rollup.total as keyof typeof summaries];
569	      const colVal = summaries[rollup.col as keyof typeof summaries];
570	      if (typeof totalVal === 'number' && totalVal !== 0 && typeof colVal === 'number') {
571	        universeRow[rollup.col + '_pct'] = colVal / totalVal;
572	      }
573	    });
574	    this.universeTotals = universeRow as SummaryRecord;
575	    useChartStore.getState().setDataUpdateHash(`${performance.now()}`);
576	  }
