578	  calculateSummaryStats(ids: string[], _columns?: string[]): Array<Record<string, number>> {
579	    if (!this.table) return [];
580	    const columns = this.table.columnNames().filter(f => !_columns || _columns.includes(f));
581	    const rows = this.table
582	      .params({
583	        _hoverIds: ids,
584	      }) // @ts-expect-error
585	      .filter((d, $) => op.includes($._hoverIds, d.path))
586	      .rollup(getRollups(columns, 'sum'))
587	      .derive(getPctDerives(columns));
588	    return rows.objects();
589	  }
