591	  /**
592	   * Helper to manage the arquero quantile function.
593	   *
594	   * Uses `overlayTable` (VTD-level choropleth data) when available,
595	   * falling back to `table` (zone-level data) for editor mode where
596	   * overlayTable is never populated.
597	   */
598	  calculateQuantiles(
599	    config: MapVariableConfig,
600	    variableName: string,
601	    numberOfBins: number
602	  ): {quantilesObject: {[q: string]: number}; quantilesList: number[]} | null {
603	    const dataTable = this.overlayTable ?? this.table;
604	    if (!dataTable) return null;
605	    const derives = {
606	      quantileVariable: config.expression
607	        ? escape(config.expression)
608	        : escape((row: Record<string, number>) => row[variableName]),
609	    };
610	    const rollups = new Array(numberOfBins + 1)
611	      .fill(0)
612	      .map((f, i) => (i === 0 ? i : Math.round((1 / numberOfBins) * i * 100) / 100))
613	      .reduce(
614	        (acc, curr, i) => {
615	          acc[`q${curr * 100}`] = op.quantile('quantileVariable', curr);
616	          return acc;
617	        },
618	        {} as {[key: string]: ReturnType<typeof op.quantile>}
619	      );
620	    const quantilesObject = dataTable.derive(derives).rollup(rollups).objects()[0] as {
621	      [q: string]: number;
622	    };
623	    const quantilesList = Object.values(quantilesObject)
624	      .sort((a, b) => a - b)
625	      .slice(1, -1);
626	    return {
627	      quantilesObject,
628	      quantilesList,
629	    };
630	  }
