632	  paintDemography({
633	    config,
634	    variableName,
635	    mapRef,
636	    ids,
637	  }: {
638	    config: MapVariableConfig;
639	    variableName: string;
640	    mapRef: maplibregl.Map;
641	    ids?: string[];
642	  }) {
643	    // Use overlayTable (VTD-level) when available; fall back to table (zone-level).
644	    const dataTable = this.overlayTable ?? this.table;
645	    if (!dataTable || !this.colorScale) return;
646	    const source = mapRef.getSource(BLOCK_SOURCE_ID) as {type?: string} | undefined;
647	    const useVectorSourceLayer = source?.type === 'vector';
648	    const colorScale = this.colorScale!;
649	
650	    if (!useVectorSourceLayer) {
651	      this.populations.forEach(row => {
652	        const zone = row.zone;
653	        if (!zone) return;
654	        const zoneId = String(zone);
655	        if (ids && !ids.includes(zoneId)) return;
656	        const value = config.expression
657	          ? config.expression(row as unknown as DemographyRow)
658	          : (row[variableName as keyof typeof row] as number | undefined);
659	        let color = '#CCCCCC';
660	        if (value !== undefined && !isNaN(+value)) {
661	          color = colorScale(+value);
662	        }
663	        mapRef.setFeatureState(
664	          {
665	            source: BLOCK_SOURCE_ID,
666	            id: zoneId,
667	          },
668	          {
669	            color,
670	            hasColor: true,
671	          }
672	        );
673	      });
674	      return;
675	    }
676	
677	    const derives = {
678	      color: config.expression
679	        ? escape(config.expression)
680	        : escape((row: Record<string, number>) => row[variableName]),
681	    };
682	    let rows = dataTable.derive(derives).select('path', 'sourceLayer', 'color');
683	    if (ids) {
684	      rows = rows.filter(escape((row: TableRow) => ids.includes(row.path)));
685	    }
686	    (rows.objects() as Array<TableRow & {color: number}>).forEach(row => {
687	      const id = row.path;
688	      if (!id) return;
689	      const value = row['color'];
690	      let color = '#CCCCCC';
691	      if (!isNaN(+value)) {
692	        color = colorScale(+value);
693	      }
694	      mapRef.setFeatureState(
695	        {
696	          source: BLOCK_SOURCE_ID,
697	          sourceLayer: useVectorSourceLayer ? row.sourceLayer : undefined,
698	          id,
699	        },
700	        {
701	          color,
702	          hasColor: true,
703	        }
704	      );
705	    });
706	  }
