708	  /**
709	   * Paints the sized-circles mode: circles at unit centroids on the selection
710	   * point sources, sized by the universe total population and shaded by the
711	   * current color scale (typically the percent share).
712	   */
713	  paintSizedCircles({
714	    config,
715	    variableName,
716	    mapRef,
717	  }: {
718	    config: MapVariableConfig;
719	    variableName: string;
720	    mapRef: maplibregl.Map;
721	  }) {
722	    const dataTable = this.overlayTable ?? this.table;
723	    if (!dataTable || !this.colorScale) return;
724	    const colorScale = this.colorScale;
725	    // Universe total for the selected variable: race groups and totals resolve via
726	    // rollup config; voter history via its derived `*_total` column.
727	    const sizeColumn =
728	      config.sizeColumn ??
729	      possibleRollups.find(r => r.col === config.value)?.total ??
730	      possibleDerivedColumns.find(d => d.column === config.value && d.label.endsWith('_total'))
731	        ?.label;
732	    if (!sizeColumn) return;
733	    const derives = {
734	      colorValue: config.expression
735	        ? escape(config.expression)
736	        : escape((row: Record<string, number>) => row[variableName]),
737	      sizeValue: escape((row: Record<string, number>) => row[sizeColumn]),
738	    };
739	    const rows = dataTable
740	      .derive(derives)
741	      .select('path', 'sourceLayer', 'colorValue', 'sizeValue')
742	      .objects() as Array<TableRow & {colorValue: number; sizeValue: number}>;
743	    const maxSize = rows.reduce((max, row) => Math.max(max, row.sizeValue || 0), 0);
744	    if (!maxSize) return;
745	    const parentLayer = useMapStore.getState().mapDocument?.parent_layer;
746	    rows.forEach(row => {
747	      if (!row.path) return;
748	      const color = isNaN(+row.colorValue) ? '#CCCCCC' : colorScale(+row.colorValue);
749	      // sqrt so circle AREA is proportional to population
750	      const radius =
751	        row.sizeValue > 0 ? MAX_SIZED_CIRCLE_RADIUS_PX * Math.sqrt(row.sizeValue / maxSize) : 0;
752	      mapRef.setFeatureState(
753	        {
754	          source:
755	            row.sourceLayer === parentLayer
756	              ? SELECTION_POINTS_SOURCE_ID
757	              : SELECTION_POINTS_SOURCE_ID_CHILD,
758	          id: row.path,
759	        },
760	        {color, radius, hasColor: true}
761	      );
762	    });
763	  }
