765	  /**
766	   * Generates a color scale for demographic data and applies it to the map.
767	   *
768	   * @param {Object} params - The parameters for generating the color scale.
769	   * @param {AllDemographyVariables} params.variable - The demographic variable to visualize.
770	   * @param {maplibregl.Map} params.mapRef - The reference to the map instance.
771	   * @param {MapStore['mapDocument']} params.mapDocument - The map document from the store.
772	   * @param {number} params.numberOfBins - The number of bins for the color scale.
773	   * @param {boolean} params.paintMap - Whether to paint the map with the generated color scale.
774	   *
775	   * @returns {d3.ScaleThreshold<number, string> | undefined} The generated color scale or undefined if prerequisites are not met.
776	   */
777	  calculateDemographyColorScale({
778	    variable,
779	    variant,
780	    mapRef,
781	    mapDocument,
782	    numberOfBins,
783	    paintMap,
784	    coalitionGroups = [],
785	  }: {
786	    variable: DemographyVariable;
787	    variant: 'percent' | 'raw';
788	    mapRef: maplibregl.Map;
789	    mapDocument: MapStore['mapDocument'];
790	    numberOfBins: number;
791	    paintMap?: boolean;
792	    coalitionGroups?: CoalitionGroupKey[];
793	  }) {
794	    const dataSoureExists = mapRef?.getSource(BLOCK_SOURCE_ID);
795	    let config: MapVariableConfig | undefined = Object.values(choroplethMapVariables)
796	      .flat()
797	      .find(v => v.value === variable);
798	
799	    if ((!this.table && !this.overlayTable) || !dataSoureExists) return;
800	    if (!config && isCoalitionVariable(variable)) {
801	      const universe =
802	        variable === COALITION_VARIABLE_BY_UNIVERSE.TOTPOP
803	          ? SUMMARY_TYPES.TOTPOP
804	          : SUMMARY_TYPES.VAP;
805	      const totalColumn = COALITION_TOTAL_COLUMN_BY_UNIVERSE[universe];
806	      const coalitionColumns = this.getCoalitionColumns(coalitionGroups, universe);
807	      if (!coalitionColumns.length) return;
808	      config = {
809	        value: variable,
810	        variants: ['percent', 'raw'],
811	        sizeColumn: totalColumn,
812	        expression: (row: Record<string, number>) => {
813	          const coalitionTotal = coalitionColumns.reduce((sum, column) => {
814	            const value = row[column];
815	            return sum + (Number.isFinite(value) ? value : 0);
816	          }, 0);
817	          if (variant === 'raw') return coalitionTotal;
818	          const total = row[totalColumn];
819	          return Number.isFinite(total) && total > 0 ? coalitionTotal / total : NaN;
820	        },
821	      };
822	    }
823	    if (!config) return;
824	    const variableName = (
825	      variant === 'percent' && config.variants?.includes('percent')
826	        ? `${config.value}_pct`
827	        : config.value
828	    ) as string;
829	    const isTotal = !config.variants;
830	    if (config.fixedScale) {
831	      this.colorScale = config.fixedScale as AnyD3Scale;
832	    } else if (isTotal || (variant === 'percent' && config.variants?.includes('percent'))) {
833	      // Unclassed continuous scale: 0-100% for share-of-population maps,
834	      // 0-max for total population maps
835	      const displayMode = useMapControlsStore.getState().mapOptions.demographicDisplayMode;
836	      // Grayscale only for the polygon overlay atop colored districts;
837	      // circles shade transparent-to-black so district colors show through
838	      const interpolator =
839	        displayMode === DEMOGRAPHIC_MODES.SIZED_CIRCLES
840	          ? SIZED_CIRCLE_COLOR_SCHEME
841	          : displayMode === DEMOGRAPHIC_MODES.OVERLAY
842	            ? DEFAULT_CONTINUOUS_COLOR_SCHEME_GRAY
843	            : DEFAULT_CONTINUOUS_COLOR_SCHEME;
844	      let domainMax = 1;
845	      if (isTotal) {
846	        const dataTable = (this.overlayTable ?? this.table)!;
847	        const stats = dataTable.rollup({maxValue: op.max(variableName)}).objects()[0] as {
848	          maxValue?: number;
849	        };
850	        domainMax = stats?.maxValue || 1;
851	      }
852	      this.colorScale = scale
853	        .scaleSequential(interpolator)
854	        .domain([0, domainMax])
855	        .clamp(true) as AnyD3Scale;
856	    } else {
857	      const quantiles = this.calculateQuantiles(config, variableName, numberOfBins);
858	      if (!quantiles) return;
859	      const uniqueQuantiles = Array.from(new Set(quantiles.quantilesList));
860	      const actualBinsLength = Math.min(numberOfBins, uniqueQuantiles.length + 1);
861	
862	      const displayMode = useMapControlsStore.getState().mapOptions.demographicDisplayMode;
863	      const defaultColor =
864	        displayMode === DEMOGRAPHIC_MODES.OVERLAY
865	          ? DEFAULT_COLOR_SCHEME_GRAY
866	          : DEFAULT_COLOR_SCHEME;
867	      let colorscheme = defaultColor[Math.max(3, actualBinsLength)];
868	
869	      if (actualBinsLength < 3) {
870	        colorscheme = colorscheme.slice(0, actualBinsLength);
871	      }
872	      this.colorScale = scale
873	        .scaleThreshold<number, string>()
874	        .domain(uniqueQuantiles)
875	        .range(colorscheme);
876	    }
877	    if (paintMap) {
878	      const displayMode = useMapControlsStore.getState().mapOptions.demographicDisplayMode;
879	      if (displayMode === DEMOGRAPHIC_MODES.SIZED_CIRCLES) {
880	        this.paintSizedCircles({config, variableName, mapRef});
881	      } else {
882	        this.paintDemography({
883	          config,
884	          variableName,
885	          mapRef,
886	        });
887	      }
888	    }
889	    return this.colorScale;
890	  }
891	
892	  /**
893	   * Updates the populations based on zone assignments.
894	   *
895	   * @param zoneAssignments - The zone assignments to use for updating populations.
896	   */
897	  updatePopulations(
898	    {
899	      zoneAssignments,
900	      coalitionGroups,
901	    }: {
902	      zoneAssignments?: PopulationAssignments;
903	      coalitionGroups: CoalitionGroupKey[];
904	    } = {
905	      coalitionGroups: [],
906	    }
907	  ) {
