909	    if (populations.ok) {
910	      useChartStore.getState().setDataUpdateHash(`${performance.now()}`);
911	      return true;
912	    } else {
913	      return false;
914	    }
915	    // .max .range
916	  }
917	
918	  getCoalitionUniverseStats(summaryType: CoalitionUniverse, coalitionGroups: CoalitionGroupKey[]) {
919	    const summaryStats = this.summaryStats[summaryType] as Record<string, number> | undefined;
920	    if (!summaryStats) {
921	      return {
922	        universeTotal: 0,
923	        coalitionTotal: 0,
924	        coalitionPct: NaN,
925	        availableGroups: [] as CoalitionGroupKey[],
926	        missingGroups: [] as CoalitionGroupKey[],
927	      };
928	    }
929	    const totalColumn = COALITION_TOTAL_COLUMN_BY_UNIVERSE[summaryType];
930	    const selectedColumns = this.getCoalitionColumns(coalitionGroups, summaryType);
931	    const universeTotal = summaryStats[totalColumn] ?? 0;
932	    const coalitionTotal = selectedColumns.reduce((sum, column) => {
933	      const value = summaryStats[column];
934	      return sum + (Number.isFinite(value) ? value : 0);
935	    }, 0);
936	    return {
937	      universeTotal,
